import React, { useState, useEffect, useCallback } from "react";
import {
  View, Text, TextInput, TouchableOpacity, ScrollView,
  StyleSheet, SafeAreaView, StatusBar, Alert, ActivityIndicator,
  Modal, FlatList, Platform,
} from "react-native";
import DateTimePicker from "@react-native-community/datetimepicker";
import * as Print from "expo-print";
import * as Sharing from "expo-sharing";
import * as FileSystem from "expo-file-system";
import { fetchParties, fetchProducts, fetchStockReport } from "../services/api";
import Icon from "../components/Icon";

// ── Date helpers ──────────────────────────────────────────────────────────────
const toApiDate = (d) => d.toISOString().split('T')[0];
const toDisplay = (d) => {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `${dd}/${mm}/${d.getFullYear()}`;
};

const FieldLabel = ({ label }) => <Text style={styles.fieldLabel}>{label}</Text>;

// ── Multi-select searchable list (inside modals) ──────────────────────────────
const MultiSearchList = ({ data, selected, onToggle, labelKey }) => {
  const [search, setSearch] = useState("");
  const filtered = data.filter(item =>
    (item[labelKey] || item.ItemCode || "").toLowerCase().includes(search.toLowerCase())
  );
  return (
    <>
      <View style={styles.searchBar}>
        <Icon name="search" size={14} color="#90a4ae" />
        <TextInput style={styles.searchInput} placeholder="Search..." value={search} onChangeText={setSearch} />
      </View>
      <FlatList
        data={filtered}
        keyExtractor={(item, i) => item.PartyID || item.ItemCode || String(i)}
        renderItem={({ item }) => {
          const id = item.PartyID || item.ItemCode;
          const isChecked = selected.some(s => (s.PartyID || s.ItemCode) === id);
          return (
            <TouchableOpacity style={[styles.listItem, { flexDirection: 'row', alignItems: 'center' }]} onPress={() => onToggle(item)}>
              <View style={[styles.cbBox, isChecked && styles.cbBoxChecked]}>
                {isChecked && <Text style={styles.cbTick}>✓</Text>}
              </View>
              <Text style={styles.listItemText}>{item[labelKey] || item.ItemCode}</Text>
            </TouchableOpacity>
          );
        }}
      />
    </>
  );
};

// ── PDF HTML builder ──────────────────────────────────────────────────────────
const buildPdfHtml = (data, filters, isSummary) => {
  const now = new Date().toLocaleString('en-IN');

  const subTableHeader = `
    <tr style="background:#dce8f5">
      <th style="width:70px">Date</th>
      <th style="width:55px">Doc #</th>
      <th style="width:80px">Description</th>
      <th style="width:55px;text-align:right">Opening</th>
      <th style="width:55px;text-align:right">Inward</th>
      <th style="width:55px;text-align:right">Outward</th>
      <th style="width:55px;text-align:right">Balance</th>
    </tr>`;

  let bodyHtml = '';
  let grandOpening = 0, grandInward = 0, grandOutward = 0, grandBalance = 0;

  if (isSummary) {
    // ── Summary: grouped by party, product table per party ───────────────────
    const groups = {};
    const partyOrder = [];
    data.forEach(r => {
      const key = r.PartyName || 'Unknown';
      if (!groups[key]) { groups[key] = []; partyOrder.push(key); }
      groups[key].push(r);
    });

    const partyBlocks = partyOrder.map(partyName => {
      const rows = groups[partyName];
      const subOp  = rows.reduce((s, r) => s + (parseFloat(r.Opening) || 0), 0);
      const subIn  = rows.reduce((s, r) => s + (parseFloat(r.Inward)  || 0), 0);
      const subOut = rows.reduce((s, r) => s + (parseFloat(r.Outward) || 0), 0);
      const subBal = rows.reduce((s, r) => s + (parseFloat(r.Balance) || 0), 0);
      grandInward += subIn; grandOutward += subOut; grandBalance += subBal;

      const productRows = rows.map((r, i) => {
        return `<tr style="background:${i % 2 === 0 ? '#f8faff' : '#fff'}">
          <td><b>${r.ProductName || '-'}</b><br/><span style="font-size:10px;color:#0056b3">${r.ItemCode || ''}</span></td>
          <td style="text-align:right">${parseFloat(r.Opening || 0).toFixed(2)}</td>
          <td style="text-align:right">${parseFloat(r.Inward  || 0).toFixed(2)}</td>
          <td style="text-align:right">${parseFloat(r.Outward || 0).toFixed(2)}</td>
          <td style="text-align:right;color:#d32f2f;font-weight:700">${parseFloat(r.Balance || 0).toFixed(2)}</td>
        </tr>`;
      }).join('');

      return `
        <div class="party-block">
          <div class="party-block-header">${partyName}</div>
          <table>
            <thead>
              <tr style="background:#888;color:#fff">
                <th>Product Name and Code</th>
                <th style="text-align:right">Opening</th>
                <th style="text-align:right">Inward</th>
                <th style="text-align:right">Outward</th>
                <th style="text-align:right">Balance</th>
              </tr>
            </thead>
            <tbody>
              ${productRows}
              <tr style="background:#e8f0fb;font-weight:700">
                <td style="text-align:center;letter-spacing:2px">......T O T A L......</td>
                <td style="text-align:right">${subOp.toFixed(2)}</td>
                <td style="text-align:right">${subIn.toFixed(2)}</td>
                <td style="text-align:right">${subOut.toFixed(2)}</td>
                <td style="text-align:right;color:#d32f2f">${subBal.toFixed(2)}</td>
              </tr>
            </tbody>
          </table>
        </div>`;
    }).join('');

    bodyHtml = partyBlocks;
  } else {
    // ── Detail: group by Product ───────────────────────────────────────────────
    const groups = {};
    const order  = [];
    data.forEach(r => {
      const key = r.ItemCode || r.ProductName || '-';
      if (!groups[key]) { groups[key] = { rows: [], partyName: r.PartyName, productName: r.ProductName, itemCode: r.ItemCode }; order.push(key); }
      groups[key].rows.push(r);
    });

    bodyHtml = order.map(key => {
      const g   = groups[key];
      const subOp  = g.rows.reduce((s, r) => s + (parseFloat(r.Opening)  || 0), 0);
      const subIn  = g.rows.reduce((s, r) => s + (parseFloat(r.Inward)   || 0), 0);
      const subOut = g.rows.reduce((s, r) => s + (parseFloat(r.Outward)  || 0), 0);
      const subBal = g.rows.reduce((s, r) => s + (parseFloat(r.Balance)  || 0), 0);
      grandOpening += subOp; grandInward += subIn; grandOutward += subOut; grandBalance += subBal;

      const dataRows = g.rows.map((r, i) => `
        <tr style="background:${i % 2 === 0 ? '#f8faff' : '#fff'}">
          <td>${r.OrderDate || '-'}</td>
          <td>${r.VouchNo || '-'}</td>
          <td style="color:#e65100">Opening</td>
          <td style="text-align:right">${parseFloat(r.Opening || 0).toFixed(2)}</td>
          <td style="text-align:right">${parseFloat(r.Inward  || 0).toFixed(2)}</td>
          <td style="text-align:right">${parseFloat(r.Outward || 0).toFixed(2)}</td>
          <td style="text-align:right;color:#d32f2f;font-weight:700">${parseFloat(r.Balance || 0).toFixed(2)}</td>
        </tr>`).join('');

      return `
        <div class="product-block">
          <div class="product-header">
            <span class="prod-name">${g.productName || '-'}</span>
            <span class="party-name-inline">${g.partyName || ''}</span>
          </div>
          <table>
            <thead>${subTableHeader}</thead>
            <tbody>
              ${dataRows}
              <tr class="sub-total">
                <td colspan="3" style="text-align:center;letter-spacing:2px">......T O T A L......</td>
                <td style="text-align:right;font-weight:700">${subOp.toFixed(2)}</td>
                <td style="text-align:right;font-weight:700">${subIn.toFixed(2)}</td>
                <td style="text-align:right;font-weight:700">${subOut.toFixed(2)}</td>
                <td style="text-align:right;font-weight:700;color:#d32f2f">${subBal.toFixed(2)}</td>
              </tr>
            </tbody>
          </table>
        </div>`;
    }).join('');
  }

  const title = isSummary
    ? `Stock Report Summary From &nbsp;<span class="date">${filters.fromDate}</span>&nbsp; To &nbsp;<span class="date">${filters.toDate}</span>`
    : `Stock Report From &nbsp;<span class="date">${filters.fromDate}</span>&nbsp; To &nbsp;<span class="date">${filters.toDate}</span>`;

  return `<!DOCTYPE html><html><head><meta charset="UTF-8"/>
  <style>
    body{font-family:Arial,sans-serif;margin:0;padding:16px;color:#222;font-size:12px;}
    h2{margin:0 0 12px;font-size:15px;}
    .date{color:#0056b3;font-weight:700;font-size:15px;}
    table{width:100%;border-collapse:collapse;margin-bottom:0;font-size:11px;}
    th{background:#888;color:#fff;padding:5px 4px;text-align:left;border:1px solid #c5d8ee;font-size:10px;}
    td{padding:4px;border:1px solid #e0e6f0;vertical-align:top;}
    /* Summary: party blocks */
    .party-block{margin-bottom:16px;border:1px solid #e0e7ef;border-radius:4px;overflow:hidden;}
    .party-block-header{background:#e65100;color:#fff;font-weight:800;font-size:12px;text-align:center;padding:7px 10px;letter-spacing:.5px;}
    /* Detail: product blocks */
    .product-block{margin-bottom:14px;border:1px solid #b0c8e8;border-radius:4px;overflow:hidden;}
    .product-header{background:#f0f4ff;padding:5px 8px;display:flex;justify-content:space-between;border-bottom:1px solid #b0c8e8;}
    .prod-name{font-weight:700;color:#1a237e;font-size:11px;}
    .party-name-inline{color:#0056b3;font-weight:700;font-size:11px;}
    .sub-total td{background:#e8f0fb;font-weight:600;}
    .footer{margin-top:14px;text-align:right;font-size:10px;color:#777;}
  </style></head><body>
  <h2>${title}</h2>
  ${bodyHtml}
  <div class="footer">Generated: ${now}</div>
</body></html>`;
};

// ── Main Screen ───────────────────────────────────────────────────────────────
export default function StockReportScreen({ navigation }) {
  const [loading, setLoading]         = useState(false);
  const [pdfLoading, setPdfLoading]   = useState(false);
  const [dropdownLoading, setDropdownLoading] = useState(false);
  const [reportData, setReportData]   = useState(null);

  const [allParties, setAllParties]   = useState([]);
  const [allProducts, setAllProducts] = useState([]);
  const [parties, setParties]         = useState([]);
  const [products, setProducts]       = useState([]);

  const today = new Date();
  const [fromDate, setFromDate]             = useState(today);
  const [toDate, setToDate]                 = useState(today);
  const [showFromPicker, setShowFromPicker] = useState(false);
  const [showToPicker, setShowToPicker]     = useState(false);

  const [selectedParties,  setSelectedParties]  = useState([]);
  const [selectedProducts, setSelectedProducts] = useState([]);
  const [isSummary, setIsSummary] = useState(true); // locked to summary; detail hidden for now

  const [tempParties,  setTempParties]  = useState([]);
  const [tempProducts, setTempProducts] = useState([]);

  const [showPartyModal,   setShowPartyModal]   = useState(false);
  const [showProductModal, setShowProductModal] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const [pData, prodData] = await Promise.all([fetchParties({ grpName: 'CREDITORS' }), fetchProducts()]);
        setAllParties(pData.data || []);    setParties(pData.data || []);
        setAllProducts(prodData.data || []); setProducts(prodData.data || []);
      } catch (e) { console.error("Failed to load stock dropdowns", e); }
    })();
  }, []);

  const toggleParty = useCallback((party) => {
    setTempParties(prev =>
      prev.some(p => p.PartyID === party.PartyID)
        ? prev.filter(p => p.PartyID !== party.PartyID)
        : [...prev, party]
    );
  }, []);

  const confirmPartySelection = useCallback(async () => {
    setSelectedParties(tempParties); setSelectedProducts([]); setReportData(null);
    setShowPartyModal(false);
    if (tempParties.length === 0) { setProducts(allProducts); return; }
    setDropdownLoading(true);
    try {
      const prodData = await fetchProducts({ partyId: tempParties.map(p => p.PartyID).join(',') });
      setProducts(prodData.data || []);
    } catch (e) { console.error(e); } finally { setDropdownLoading(false); }
  }, [tempParties, allProducts]);

  const toggleProduct = useCallback((product) => {
    setTempProducts(prev =>
      prev.some(p => p.ItemCode === product.ItemCode)
        ? prev.filter(p => p.ItemCode !== product.ItemCode)
        : [...prev, product]
    );
  }, []);

  const confirmProductSelection = useCallback(async () => {
    setSelectedProducts(tempProducts); setReportData(null);
    setShowProductModal(false);
    if (tempProducts.length === 0) { setParties(allParties); return; }
    setDropdownLoading(true);
    try {
      const pData = await fetchParties({ productId: tempProducts.map(p => p.ItemCode).join(','), grpName: 'CREDITORS' });
      setParties(pData.data || []);
    } catch (e) { console.error(e); } finally { setDropdownLoading(false); }
  }, [tempProducts, allParties]);

  const handleReset = () => {
    setSelectedParties([]); setSelectedProducts([]);
    setTempParties([]); setTempProducts([]);
    setFromDate(new Date()); setToDate(new Date());
    setIsSummary(true); setReportData(null);
    setParties(allParties); setProducts(allProducts);
  };

  const handleGenerateReport = async () => {
    const isAllAll = selectedParties.length === 0 && selectedProducts.length === 0;

    // For All x All, show a warning that it may take longer
    if (isAllAll) {
      Alert.alert(
        'All Parties & All Products',
        'This will load stock data for all parties and all products. It may take up to 60 seconds. Do you want to continue?',
        [
          { text: 'Cancel', style: 'cancel' },
          { text: 'Continue', onPress: () => _doFetch() },
        ]
      );
      return;
    }
    _doFetch();
  };

  const _doFetch = async () => {
    setLoading(true); setReportData(null);
    try {
      const res = await fetchStockReport({
        fromDate:  toApiDate(fromDate),
        toDate:    toApiDate(toDate),
        partyId:   selectedParties.length  > 0 ? selectedParties.map(p => p.PartyID).join(',')   : 'All',
        productId: selectedProducts.length > 0 ? selectedProducts.map(p => p.ItemCode).join(',') : 'All',
        summary:   isSummary,
      });
      if (res.success && res.data?.length > 0) setReportData(res.data);
      else Alert.alert('No Data', res.message || 'No records found for the selected filters.');
    } catch (e) {
      const msg = e?.response?.data?.message || e.message || 'Failed to generate stock report.';
      Alert.alert('Error', msg);
    }
    finally { setLoading(false); }
  };

  const handleDownloadPdf = async () => {

    if (!reportData) return;
    setPdfLoading(true);
    try {
      const partyLabel   = selectedParties.length  > 0 ? selectedParties.map(p => p.PartyName).join(', ')  : null;
      const productLabel = selectedProducts.length > 0 ? selectedProducts.map(p => p.ItemCode).join(', ')  : null;
      const html = buildPdfHtml(reportData, {
        fromDate: toDisplay(fromDate), toDate: toDisplay(toDate),
        partyName: partyLabel, productName: productLabel,
      }, isSummary);
      const { uri } = await Print.printToFileAsync({ html, base64: false });
      const safeParty   = (partyLabel   || 'AllParties').replace(/[^a-zA-Z0-9]/g, '_');
      const safeProduct = (productLabel || 'AllProducts').replace(/[^a-zA-Z0-9]/g, '_');
      const today = toDisplay(new Date()).replace(/\//g, '-');
      const mode = isSummary ? 'Summary' : 'Detail';
      const fileName = `Stock_${mode}_${safeParty}_${safeProduct}_${today}.pdf`;
      const destUri = `${FileSystem.cacheDirectory}${fileName}`;
      await FileSystem.copyAsync({ from: uri, to: destUri });
      if (await Sharing.isAvailableAsync()) {
        await Sharing.shareAsync(destUri, { mimeType: "application/pdf", dialogTitle: "Stock Report", UTI: "com.adobe.pdf" });
      } else {
        Alert.alert("PDF Saved", `Saved as: ${fileName}`);
      }
    } catch (e) { Alert.alert("Error", "Failed to generate PDF."); }
    finally { setPdfLoading(false); }
  };

  // ── Detail mode: group by Product ────────────────────────────────────────
  const renderDetailResults = () => {
    // Build groups keyed by ItemCode
    const groups = {};
    const order  = [];
    reportData.forEach(r => {
      const key = r.ItemCode || r.ProductName || '-';
      if (!groups[key]) { groups[key] = { productName: r.ProductName, itemCode: r.ItemCode, partyName: r.PartyName, rows: [] }; order.push(key); }
      groups[key].rows.push(r);
    });

    const ColHeader = () => (
      <View style={[styles.tableHeader, { backgroundColor: '#dce8f5' }]}>
        <Text style={[styles.th, { flex: 1.1, color: '#1a237e' }]}>Date</Text>
        <Text style={[styles.th, { flex: 0.8, color: '#1a237e' }]}>Doc #</Text>
        <Text style={[styles.th, { flex: 1.0, color: '#1a237e' }]}>Desc.</Text>
        <Text style={[styles.th, { flex: 0.8, color: '#1a237e', textAlign: 'right' }]}>Opening</Text>
        <Text style={[styles.th, { flex: 0.7, color: '#1a237e', textAlign: 'right' }]}>Inward</Text>
        <Text style={[styles.th, { flex: 0.7, color: '#1a237e', textAlign: 'right' }]}>Outward</Text>
        <Text style={[styles.th, { flex: 0.8, color: '#1a237e', textAlign: 'right' }]}>Balance</Text>
      </View>
    );

    let grandIn = 0, grandOut = 0, grandBal = 0;

    return (
      <>
        {order.map(key => {
          const g = groups[key];
          const subIn  = g.rows.reduce((s, r) => s + (parseFloat(r.Inward)  || 0), 0);
          const subOut = g.rows.reduce((s, r) => s + (parseFloat(r.Outward) || 0), 0);
          const subBal = g.rows.reduce((s, r) => s + (parseFloat(r.Balance) || 0), 0);
          grandIn += subIn; grandOut += subOut; grandBal += subBal;
          return (
            <View key={key} style={styles.productBlock}>
              {/* Product header: name left, party right */}
              <View style={styles.productGroupHeader}>
                <Text style={styles.productGroupName} numberOfLines={2}>{g.productName || key}</Text>
                <Text style={styles.productGroupParty} numberOfLines={1}>{g.partyName || ''}</Text>
              </View>
              <ColHeader />
              {g.rows.map((r, i) => (
                <View key={i} style={[styles.tableRow, i % 2 === 0 && { backgroundColor: '#f8faff' }]}>
                  <Text style={[styles.td, { flex: 1.1, fontSize: 10 }]}>{r.OrderDate || '-'}</Text>
                  <Text style={[styles.td, { flex: 0.8, fontSize: 10 }]}>{r.VouchNo || '-'}</Text>
                  <Text style={[styles.td, { flex: 1.0, fontSize: 10, color: '#e65100' }]}>Opening</Text>
                  <Text style={[styles.td, { flex: 0.8, textAlign: 'right', fontSize: 10 }]}>{parseFloat(r.Opening || 0).toFixed(2)}</Text>
                  <Text style={[styles.td, { flex: 0.7, textAlign: 'right', fontSize: 10 }]}>{parseFloat(r.Inward  || 0).toFixed(2)}</Text>
                  <Text style={[styles.td, { flex: 0.7, textAlign: 'right', fontSize: 10 }]}>{parseFloat(r.Outward || 0).toFixed(2)}</Text>
                  <Text style={[styles.tdBal, { flex: 0.8, fontSize: 10 }]}>{parseFloat(r.Balance || 0).toFixed(2)}</Text>
                </View>
              ))}
              {/* Subtotal */}
              <View style={styles.subtotalRow}>
                <Text style={[styles.tdBold, { flex: 2.9, color: '#555', letterSpacing: 1 }]}>......T O T A L......</Text>
                <Text style={[styles.td, { flex: 0.8, textAlign: 'right', fontWeight: '700', color: '#1a237e', fontSize: 10 }]}>{g.rows.reduce((s, r) => s + (parseFloat(r.Opening) || 0), 0).toFixed(2)}</Text>
                <Text style={[styles.td, { flex: 0.7, textAlign: 'right', fontWeight: '700', color: '#0056b3', fontSize: 10 }]}>{subIn.toFixed(2)}</Text>
                <Text style={[styles.td, { flex: 0.7, textAlign: 'right', fontWeight: '700', color: '#0056b3', fontSize: 10 }]}>{subOut.toFixed(2)}</Text>
                <Text style={[styles.tdBal, { flex: 0.8, fontSize: 11 }]}>{subBal.toFixed(2)}</Text>
              </View>
            </View>
          );
        })}
      </>
    );
  };


  // ── Summary mode: group by Party ───────────────────────────────────
  const renderSummaryResults = () => {
    // Build groups keyed by PartyName
    const groups = {};
    const order  = [];
    reportData.forEach(r => {
      const key = r.PartyName || 'Unknown Party';
      if (!groups[key]) { groups[key] = []; order.push(key); }
      groups[key].push(r);
    });

    return (
      <>
        {order.map(partyName => {
          const rows = groups[partyName];
          const subOpening = rows.reduce((s, r) => s + (parseFloat(r.Opening) || 0), 0);
          const subInward  = rows.reduce((s, r) => s + (parseFloat(r.Inward)  || 0), 0);
          const subOutward = rows.reduce((s, r) => s + (parseFloat(r.Outward) || 0), 0);
          const subBalance = rows.reduce((s, r) => s + (parseFloat(r.Balance) || 0), 0);
          return (
            <View key={partyName} style={styles.partyGroup}>
              {/* Party header — orange background like the web app */}
              <View style={styles.partyGroupHeader}>
                <Text style={styles.partyGroupTitle}>{partyName}</Text>
              </View>
              {/* Column headers */}
              <View style={styles.tableHeader}>
                <Text style={[styles.th, { flex: 2.2 }]}>Product Name and Code</Text>
                <Text style={[styles.th, { flex: 0.8, textAlign: 'right' }]}>Opening</Text>
                <Text style={[styles.th, { flex: 0.8, textAlign: 'right' }]}>Inward</Text>
                <Text style={[styles.th, { flex: 0.8, textAlign: 'right' }]}>Outward</Text>
                <Text style={[styles.th, { flex: 0.8, textAlign: 'right' }]}>Balance</Text>
              </View>
              {/* Product rows */}
              {rows.map((r, i) => (
                <View key={i} style={[styles.tableRow, i % 2 === 0 && { backgroundColor: '#f8faff' }]}>
                  <View style={{ flex: 2.2 }}>
                    <Text style={styles.tdBold} numberOfLines={2}>{r.ProductName || '-'}</Text>
                    <Text style={[styles.tdSub, { color: '#0056b3' }]}>{r.ItemCode || ''}</Text>
                  </View>
                  <Text style={[styles.td, { flex: 0.8, textAlign: 'right' }]}>{parseFloat(r.Opening || 0).toFixed(2)}</Text>
                  <Text style={[styles.td, { flex: 0.8, textAlign: 'right' }]}>{parseFloat(r.Inward  || 0).toFixed(2)}</Text>
                  <Text style={[styles.td, { flex: 0.8, textAlign: 'right' }]}>{parseFloat(r.Outward || 0).toFixed(2)}</Text>
                  <Text style={[styles.tdBal, { flex: 0.8, textAlign: 'right' }]}>{parseFloat(r.Balance || 0).toFixed(2)}</Text>
                </View>
              ))}
              {/* Party subtotal */}
              <View style={styles.subtotalRow}>
                <Text style={[styles.tdBold, { flex: 2.2, letterSpacing: 1, color: '#37474f' }]}>......T O T A L......</Text>
                <Text style={[styles.td, { flex: 0.8, textAlign: 'right', fontWeight: '700' }]}>{subOpening.toFixed(2)}</Text>
                <Text style={[styles.td, { flex: 0.8, textAlign: 'right', fontWeight: '700', color: '#0056b3' }]}>{subInward.toFixed(2)}</Text>
                <Text style={[styles.td, { flex: 0.8, textAlign: 'right', fontWeight: '700', color: '#0056b3' }]}>{subOutward.toFixed(2)}</Text>
                <Text style={[styles.tdBal, { flex: 0.8, textAlign: 'right', fontSize: 13 }]}>{subBalance.toFixed(2)}</Text>
              </View>
            </View>
          );
        })}
      </>
    );
  };



  return (
    <SafeAreaView style={styles.safe}>
      <StatusBar backgroundColor="#0056b3" barStyle="light-content" />
      <View style={styles.header}>
        <TouchableOpacity style={styles.headerBack} onPress={() => navigation.goBack()}>
          <Icon name="back" size={22} color="#fff" />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Stock Report</Text>
        <TouchableOpacity onPress={handleReset} style={{ padding: 4 }}>
          <Text style={{ color: '#fff', fontSize: 13, fontWeight: '700' }}>RESET</Text>
        </TouchableOpacity>
      </View>

      <ScrollView style={styles.scroll} contentContainerStyle={styles.scrollContent}>
        <View style={styles.card}>
          <Text style={styles.sectionTitle}>Filters</Text>

          {dropdownLoading && (
            <View style={styles.cascadeBar}>
              <ActivityIndicator size="small" color="#0056b3" />
              <Text style={styles.cascadeText}>Updating filters…</Text>
            </View>
          )}

          {/* Dates */}
          <View style={styles.row}>
            <View style={styles.halfCol}>
              <FieldLabel label="FROM DATE" />
              <TouchableOpacity style={styles.dateBtn} onPress={() => { setShowFromPicker(true); setReportData(null); }}>
                <Icon name="calendar" size={15} color="#0056b3" />
                <Text style={styles.dateBtnText}>{toDisplay(fromDate)}</Text>
              </TouchableOpacity>
              {showFromPicker && (
                <DateTimePicker value={fromDate} mode="date"
                  display={Platform.OS === 'ios' ? 'inline' : 'calendar'}
                  onChange={(_, d) => { setShowFromPicker(Platform.OS === 'ios'); if (d) setFromDate(d); }}
                  maximumDate={toDate}
                />
              )}
            </View>
            <View style={styles.halfCol}>
              <FieldLabel label="TILL DATE" />
              <TouchableOpacity style={styles.dateBtn} onPress={() => { setShowToPicker(true); setReportData(null); }}>
                <Icon name="calendar" size={15} color="#0056b3" />
                <Text style={styles.dateBtnText}>{toDisplay(toDate)}</Text>
              </TouchableOpacity>
              {showToPicker && (
                <DateTimePicker value={toDate} mode="date"
                  display={Platform.OS === 'ios' ? 'inline' : 'calendar'}
                  onChange={(_, d) => { setShowToPicker(Platform.OS === 'ios'); if (d) setToDate(d); }}
                  minimumDate={fromDate}
                />
              )}
            </View>
          </View>

          {/* Party */}
          <FieldLabel label="PARTY NAME" />
          <TouchableOpacity style={styles.dropdown} onPress={() => { setTempParties(selectedParties); setShowPartyModal(true); }}>
            <Text style={selectedParties.length > 0 ? styles.dropdownValue : styles.dropdownPlaceholder}>
              {selectedParties.length > 0 ? `${selectedParties.length} party(s) selected` : 'All Parties'}
            </Text>
            <Icon name="chevron" size={16} color="#90a4ae" />
          </TouchableOpacity>

          {/* Product */}
          <FieldLabel label="PRODUCT" />
          <TouchableOpacity style={styles.dropdown} onPress={() => { setTempProducts(selectedProducts); setShowProductModal(true); }}>
            <Text style={selectedProducts.length > 0 ? styles.dropdownValue : styles.dropdownPlaceholder}>
              {selectedProducts.length > 0 ? `${selectedProducts.length} product(s) selected` : 'All Products'}
            </Text>
            <Icon name="chevron" size={16} color="#90a4ae" />
          </TouchableOpacity>

          {/* REPORT MODE toggle — hidden for now (detail mode reserved for future) */}
          {/* Uncomment below to re-enable Detail mode:
          <FieldLabel label="REPORT MODE" />
          <TouchableOpacity style={[styles.checkboxContainer, isSummary && styles.checkboxActive]}
            onPress={() => { setIsSummary(!isSummary); setReportData(null); }}>
            <View style={[styles.checkbox, isSummary && styles.checkboxFilled]} />
            <Text style={[styles.checkboxLabel, isSummary && { color: '#0056b3' }]}>
              {isSummary ? '📋 Summary Only (product totals)' : '📄 Detailed (per order)'}
            </Text>
          </TouchableOpacity>
          */}

          {/* Chips */}
          {(selectedParties.length > 0 || selectedProducts.length > 0) && (
            <View style={styles.chipRow}>
              {selectedParties.map(p => (
                <View key={p.PartyID} style={styles.chip}><Text style={styles.chipText}>{p.PartyName}</Text></View>
              ))}
              {selectedProducts.map(p => (
                <View key={p.ItemCode} style={styles.chip}><Text style={styles.chipText}>{p.ItemCode}</Text></View>
              ))}
            </View>
          )}

          <TouchableOpacity style={styles.generateBtn} onPress={handleGenerateReport} disabled={loading}>
            {loading
              ? <ActivityIndicator color="#fff" />
              : <><Icon name="reports" size={18} color="#fff" /><Text style={styles.generateBtnText}>GENERATE REPORT</Text></>}
          </TouchableOpacity>
        </View>

        {/* Results */}
        {reportData && (
          <View style={styles.resultsCard}>
            <View style={styles.resultsHeader}>
              <View>
                <Text style={styles.resultsTitle}>
                  {isSummary ? '📋 Summary Report' : '📄 Detail Report'}
                </Text>
                <Text style={styles.resultsCount}>{reportData.length} record(s) found</Text>
              </View>
              <TouchableOpacity style={styles.pdfBtn} onPress={handleDownloadPdf} disabled={pdfLoading}>
                {pdfLoading
                  ? <ActivityIndicator size="small" color="#fff" />
                  : <Text style={styles.pdfBtnText}>📄 PDF</Text>}
              </TouchableOpacity>
            </View>
            {isSummary ? renderSummaryResults() : renderDetailResults()}
          </View>
        )}
      </ScrollView>

      {/* Party modal */}
      <Modal visible={showPartyModal} animationType="slide" transparent>
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Select Parties</Text>
              <TouchableOpacity onPress={() => setShowPartyModal(false)}><Text style={styles.closeText}>Cancel</Text></TouchableOpacity>
            </View>
            {tempParties.length > 0 && (
              <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: '#e3f2fd', borderRadius: 10, padding: 10, marginBottom: 12 }}>
                <Text style={{ color: '#0056b3', fontWeight: '700', flex: 1 }}>{tempParties.length} party(s) selected</Text>
                <TouchableOpacity onPress={() => setTempParties([])}><Text style={{ color: '#e91e63', fontWeight: '600', fontSize: 12 }}>Clear all</Text></TouchableOpacity>
              </View>
            )}
            <MultiSearchList data={parties} selected={tempParties} onToggle={toggleParty} labelKey="PartyName" />
            <TouchableOpacity style={styles.doneBtn} onPress={confirmPartySelection}>
              <Text style={styles.doneBtnText}>DONE  ({tempParties.length} selected)</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>

      {/* Product modal */}
      <Modal visible={showProductModal} animationType="slide" transparent>
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Select Products</Text>
              <TouchableOpacity onPress={() => setShowProductModal(false)}><Text style={styles.closeText}>Cancel</Text></TouchableOpacity>
            </View>
            {tempProducts.length > 0 && (
              <View style={{ flexDirection: 'row', alignItems: 'center', backgroundColor: '#e3f2fd', borderRadius: 10, padding: 10, marginBottom: 12 }}>
                <Text style={{ color: '#0056b3', fontWeight: '700', flex: 1 }}>{tempProducts.length} product(s) selected</Text>
                <TouchableOpacity onPress={() => setTempProducts([])}><Text style={{ color: '#e91e63', fontWeight: '600', fontSize: 12 }}>Clear all</Text></TouchableOpacity>
              </View>
            )}
            <MultiSearchList data={products} selected={tempProducts} onToggle={toggleProduct} labelKey="ProductName" />
            <TouchableOpacity style={styles.doneBtn} onPress={confirmProductSelection}>
              <Text style={styles.doneBtnText}>DONE  ({tempProducts.length} selected)</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

